class Solution {
public:
    vector<string> findRepeatedDnaSequences(string s) {
        map<string, int> seen;
        vector<string> res;
        for (int r = 9; r < (int)s.size(); r++) {
            int l = r - 9;
            string strip = s.substr(l, 10);
            if (++seen[strip] == 2) res.push_back(strip);
        }
        return res;
    }
};
